import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 5500;
    static final long INF = 1000000007L;
    static int n, m, k, c, d;
    static int u, v, totalFlow = 0, s = MAXN - 2, t = MAXN - 1, parent[] = new int[MAXN];
    static long totalCost = 0, dist[] = new long[MAXN];
    static PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingLong(p -> p.first));
    static List<Edge>[] adj = new ArrayList[MAXN];

    static {
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static class Edge {
        int v, c, index, cap;
        Edge(int v, int c, int index, int cap) {
            this.v = v;
            this.c = c;
            this.index = index;
            this.cap = cap;
        }
    }

    static class Pair {
        long first;
        int second;
        Pair(long first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static void addEdge(int u, int v, int cost, int capacity) {
        int szU = adj[u].size();
        int szV = adj[v].size();
        adj[u].add(new Edge(v, cost, szV, capacity));
        adj[v].add(new Edge(u, -cost, szU, 0));
    }

    static void findShortest() {
        Arrays.fill(dist, INF);
        pq.clear();
        dist[s] = 0;
        pq.add(new Pair(0, s));
        while (!pq.isEmpty()) {
            Pair curr = pq.poll();
            long currDist = curr.first;
            int u = curr.second;
            if (currDist > dist[u]) continue;
            for (Edge e : adj[u]) {
                if (e.cap > 0 && dist[e.v] > currDist + e.c) {
                    parent[e.v] = e.index;
                    dist[e.v] = currDist + e.c;
                    pq.add(new Pair(dist[e.v], e.v));
                }
            }
        }
    }

    static void updateFlow() {
        int flowAdd = k;
        int v = t;
        while (v != s) {
            int u = adj[v].get(parent[v]).v;
            int ind = adj[v].get(parent[v]).index;
            flowAdd = Math.min(flowAdd, adj[u].get(ind).cap);
            v = u;
        }
        totalFlow += flowAdd;
        totalCost += (long) flowAdd * dist[t];
        v = t;
        while (v != s) {
            int u = adj[v].get(parent[v]).v;
            int ind = adj[v].get(parent[v]).index;
            adj[v].get(parent[v]).cap += flowAdd;
            adj[u].get(ind).cap -= flowAdd;
            v = u;
        }
    }

    static int nodeID(int u, int t) {
        return u + t * n;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            u = Integer.parseInt(st.nextToken());
            addEdge(s, nodeID(u, 0), 0, 1);
        }

        for (int i = 0; i <= n + k; i++) {
            addEdge(nodeID(1, i), t, c * i, k);
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < n + k; j++) {
                addEdge(nodeID(i, j), nodeID(i, j + 1), 0, k);
            }
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            u = Integer.parseInt(st.nextToken());
            v = Integer.parseInt(st.nextToken());
            for (int j = 0; j < k; j++) {
                for (int l = 0; l < n + k; l++) {
                    addEdge(nodeID(u, l), nodeID(v, l + 1), d * (2 * j + 1), 1);
                    addEdge(nodeID(v, l), nodeID(u, l + 1), d * (2 * j + 1), 1);
                }
            }
        }

        while (totalFlow < k) {
            findShortest();
            updateFlow();
        }

        System.out.println(totalCost);
    }
}
